import React from 'react';
import { render, screen } from '@testing-library/react';
import BeesCare from './BeesCare';

describe('BeesCare', () => {
  test('should render without crashing', () => {
    render(<BeesCare />);
    expect(screen.getByTestId('BeesCareIcon')).toBeInTheDocument();
  });
  test('should render vertical variant without crashing', () => {
    render(<BeesCare variant="vertical" colorType="onDarkBg" />);
    expect(screen.getByTitle('Bees Care Vertical Logo')).toBeInTheDocument();
  });
  test('should render icon variant without crashing', () => {
    render(<BeesCare variant="icon" colorType="onDarkBg" />);
    expect(screen.getByTitle('Bees Care Icon')).toBeInTheDocument();
  });
  test('should render with a different colorType without crashing', () => {
    render(<BeesCare colorType="onColorBg" />);
    expect(screen.getByTestId('BeesCareIcon')).toBeInTheDocument();
  });
});
